import struct
import zlib

# Read the compiled application binary generated by objcopy
with open("app.bin", "rb") as f:
    app_data = f.read()

app_size = len(app_data)
# zlib.crc32 gives the standard IEEE 802.3 CRC32 checksum
app_crc = zlib.crc32(app_data) & 0xFFFFFFFF

# Magic number ("BOOT") and initial version (1.0.0.0)
MAGIC = 0x424F4F54
VERSION = 0x00010000

# Pack into a compact binary structure (Little Endian: <, 4 Unsigned Integers: IIII)
# Fields: Magic, Size, CRC32, Version
meta_data = struct.pack("<IIII", MAGIC, app_size, app_crc, VERSION)

with open("app_meta.bin", "wb") as f:
    f.write(meta_data)

print(f"[METADATA] app.bin size: {app_size} bytes | CRC32: 0x{app_crc:08X} -> written to app_meta.bin")
